using System.Text.Json;
using Bookstore.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace Bookstore.Api.Endpoints
{
    /// <summary>
    /// Applies the supplier's weekly price list to the catalog.
    /// </summary>
    public static class SupplierPriceEndpoints
    {
        public static IEndpointRouteBuilder MapSupplierPriceEndpoints(this IEndpointRouteBuilder app)
        {
            app.MapPost("/api/books/prices/import", ImportPricesAsync).WithTags("Books");
            return app;
        }

        // POST /api/books/prices/import
        // Body (text/csv): one "isbn,price" pair per line, with an "isbn,price" header line.
        private static async Task<IResult> ImportPricesAsync(
            HttpRequest request, BookstoreDbContext db, ILogger<Program> logger, CancellationToken cancellationToken)
        {
            using var reader = new StreamReader(request.Body);
            var csv = await reader.ReadToEndAsync();

            var report = new PriceImportReport();
            foreach (var line in csv.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                var parts = line.Trim().Split(',');
                if (parts[0].ToUpper() == "ISBN")
                {
                    continue;
                }

                var isbn = parts[0].Trim().ToUpper();
                if (isbn.Length == 10)
                {
                    // TODO: convert ISBN-10 to ISBN-13 with Isbn13.Net (see ai-suggestion/SUGGESTION.md).
                    report.Skipped.Add(isbn);
                    continue;
                }

                var price = decimal.Parse(parts[1]);
                var book = await db.Books.FirstOrDefaultAsync(b => b.Isbn == isbn);
                book!.Price = price;
                report.Updated++;
            }

            db.SaveChanges();

            logger.LogInformation($"Supplier import updated {report.Updated} prices and skipped {report.Skipped.Count}.");

            var json = JsonSerializer.Serialize(report, new JsonSerializerOptions
            {
                PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
                IgnoreNullValues = true,
            });
            return Results.Content(json, "application/json");
        }

        private class PriceImportReport
        {
            public int Updated { get; set; }

            public List<string> Skipped { get; set; } = new List<string>();

            public string? Warning { get; set; }
        }
    }
}
